// Writes the per-image shot analysis into each registry/images/*/meta.json as
// a `prompt` object. Every value here was written against the actual picture;
// where a field genuinely could not be read off the image it is left as an
// empty string and dropped rather than guessed at — the Prompt tab omits
// missing fields instead of printing "N/A".
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import path from 'node:path'

// A person's descent is not something to assert from pixels, and these are
// synthetic images with no real sitter behind them. The field stays in the
// template (image models want it) but says plainly that the choice is yours.
const DESCENT = 'Not asserted — synthetic subject; specify explicitly when recreating.'

