const dirs = readdirSync('registry/images')
let written = 0
const missing = []

for (const dir of dirs) {
  const metaPath = path.join('registry/images', dir, 'meta.json')
  const meta = JSON.parse(readFileSync(metaPath, 'utf8'))
  const slug = meta.name.replace(/^image-/, '')
  const row = ROWS[slug]
  if (!row) {
    missing.push(slug)
    continue
  }

  const pick = (arr, keys) => {
    if (!arr) return undefined
    const out = {}
    keys.forEach((key, i) => {
      if (arr[i]) out[key] = arr[i]
    })
    return Object.keys(out).length ? out : undefined
  }

  const subject = row.s
    ? { ...pick(row.s, ['age', 'physical', 'expression', 'clothing']), descent: DESCENT }
    : undefined
  // Re-order so descent sits where the template expects it.
  const orderedSubject = subject
    ? {
        ...(subject.age ? { age: subject.age } : {}),
        descent: subject.descent,
        ...(subject.physical ? { physical: subject.physical } : {}),
        ...(subject.expression ? { expression: subject.expression } : {}),
        ...(subject.clothing ? { clothing: subject.clothing } : {}),
      }
    : undefined

  const prompt = {
    ...(orderedSubject ? { subject: orderedSubject } : {}),
    ...(pick(row.c, ['shotType', 'angle', 'placement', 'distance', 'depthOfField', 'focus'])
      ? { composition: pick(row.c, ['shotType', 'angle', 'placement', 'distance', 'depthOfField', 'focus']) }
      : {}),
    ...(pick(row.e, ['setting', 'background', 'depth'])
      ? { environment: pick(row.e, ['setting', 'background', 'depth']) }
      : {}),
    ...(pick(row.l, ['quality', 'direction', 'temperature', 'shadows'])
      ? { lighting: pick(row.l, ['quality', 'direction', 'temperature', 'shadows']) }
      : {}),
    ...(pick(row.m, ['lens', 'quality', 'artifacts', 'aesthetic'])
      ? { camera: pick(row.m, ['lens', 'quality', 'artifacts', 'aesthetic']) }
      : {}),
    ...(pick(row.a, ['mood', 'story', 'micro'])
      ? { atmosphere: pick(row.a, ['mood', 'story', 'micro']) }
      : {}),
  }

  // Keep `prompt` last so the diff reads cleanly against the existing file.
  const { prompt: _drop, ...rest } = meta
  writeFileSync(metaPath, JSON.stringify({ ...rest, prompt }, null, 2) + '\n')
  written++
}

console.log(`wrote prompts for ${written} images`)
if (missing.length) console.log(`no analysis for ${missing.length}: ${missing.join(', ')}`)
